/**
 * Icons. An icon is `<span class="icon icon-NAME">`: its shape comes from a CSS `mask-image` in
 * styles.css (generated by scripts/gen-icons.mjs) and its colour from `currentColor`, so it follows
 * the text colour and the theme. The host webview does not draw inline `<svg>`, a mask is an
 * ordinary element. Verdicts use the same icons, in the colour of the verdict and with a different
 * shape each (a tick, a triangle, a cross), so they never depend on colour alone.
 */

import type { Verdict } from './types';

export const ICON_NAMES = [
    'package', 'tag', 'bot', 'check', 'download', 'arrow-left', 'arrow-right', 'close', 'folder', 'archive',
    'user', 'globe', 'shield', 'file-text', 'file-code', 'palette', 'image', 'layers', 'key', 'lock', 'braces',
    'info', 'help-circle', 'check-circle', 'alert-triangle', 'x-circle', 'eye', 'trash', 'copy', 'crop', 'list', 'save', 'search', 'refresh', 'undo', 'plus', 'upload', 'pipette', 'eraser', 'wand', 'sliders', 'expand', 'rotate', 'flip',
] as const;

export type IconName = (typeof ICON_NAMES)[number];

export function icon(name: IconName, extra = ''): HTMLElement {
    const el = document.createElement('span');
    el.className = `icon icon-${name}${extra ? ` ${extra}` : ''}`;
    el.setAttribute('aria-hidden', 'true');
    return el;
}

export const VERDICT_WORD: Record<Verdict, string> = { pass: 'Pass', warning: 'Warning', fail: 'Fail' };

const VERDICT_ICON: Record<Verdict, IconName> = { pass: 'check-circle', warning: 'alert-triangle', fail: 'x-circle' };

/** The verdict as an icon: a different shape and a different colour for each. */
export function indicator(verdict: Verdict): HTMLElement {
    return icon(VERDICT_ICON[verdict], `ind ind--${verdict}`);
}
